CREATE TABLE patient_profiles(id uuid PRIMARY KEY,patient_number varchar(64) NOT NULL,first_name varchar(100) NOT NULL,last_name varchar(100) NOT NULL,date_of_birth date NOT NULL,email varchar(254) NOT NULL,phone varchar(30),emergency_contact text,allergies text,status varchar(30) NOT NULL,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO patient_profiles(id,patient_number,first_name,last_name,date_of_birth,email,phone,emergency_contact,allergies,status,version,created_at) SELECT id,data->>'patientNumber',data->>'firstName',data->>'lastName',nullif(data->>'dateOfBirth','')::date,data->>'email',data->>'phone',data->>'emergencyContact',data->>'allergies',coalesce(data->>'status','ACTIVE'),version,created_at FROM records WHERE kind='patient';
CREATE INDEX patient_profiles_owner_created ON patient_profiles(id,created_at);
CREATE UNIQUE INDEX patient_profiles_number ON patient_profiles(patient_number);ALTER TABLE care_assignments DROP CONSTRAINT care_assignments_patient_id_fkey;ALTER TABLE care_assignments ADD FOREIGN KEY(patient_id) REFERENCES patient_profiles(id);
ALTER TABLE patient_profiles ADD CONSTRAINT patient_status CHECK(status IN('ACTIVE','INACTIVE'));
